            transcriptTranslation: "ಜೈನ ಸಮಾಜದ ಕಾಶಿ — ಮಹಾರಾಷ್ಟ್ರದ ಕಾರಂಜಾ ನಗರ. ಆಚಾರ್ಯ ಸಮಂತಭದ್ರರು ಸ್ಥಾಪಿಸಿದ ಮಹಾವೀರ ದಿಗಂಬರ ಜೈನ ಗುರುಕುಲ. ಇಲ್ಲಿ ಪ್ರಾಚೀನ ಜೈನ ಸಾಹಿತ್ಯದ ಜೀರ್ಣೋದ್ಧಾರ, ಪುನರ್ಲೇಖನ, ದಾಖಲೀಕರಣ ಮತ್ತು ವ್ಯವಸ್ಥೆಯ ಕಾರ್ಯ ಶ್ರೀ ಶಾಂತಿಸಾಗರ ಫೌಂಡೇಶನ್, ಬೆಂಗಳೂರು ಇವರಿಂದ ನಡೆಯುತ್ತಿದೆ. ನಮ್ಮ ಮಂತ್ರಿಗಳಾದ […] ಅವರು, ಧನ್ಯಕುಮಾರ್ ಅವರ ಸುಪುತ್ರರು, ಜೀರ್ಣೋದ್ಧಾರದ ಎಲ್ಲ ಕಾರ್ಯಗಳನ್ನು ತೋರಿಸಿದರು. ನೋಡಿ ಬಹಳ ಸಂತೋಷವಾಯಿತು. ದೇಶದಾದ್ಯಂತದ ಜೈನ ಸಮಾಜಕ್ಕೆ ಮತ್ತು ಪ್ರಾಚೀನ ಗ್ರಂಥಗಳನ್ನು ಕಾಪಾಡಿರುವ ಎಲ್ಲರಿಗೆ ನನ್ನ ಆಶಯ: ನೀವೂ ಇಂತಹ ಜೀರ್ಣೋದ್ಧಾರವನ್ನು ಮಾಡಿಸಿ, ಇದರಿಂದ ಗ್ರಂಥಗಳು ನೂರಾರು ವರ್ಷಗಳ ಕಾಲ ಮರುಜೀವ ಪಡೆಯಲಿ, ಧರ್ಮ ಮತ್ತು ಸಂಸ್ಕೃತಿಯ ಸಂರಕ್ಷಣೆಯಾಗಲಿ. ಇದಕ್ಕಾಗಿ ಸಕಲ ಸಮಾಜಕ್ಕೂ ಫೌಂಡೇಶನ್‌ಗೂ ನನ್ನ ಬಹಳ ಬಹಳ ಆಶೀರ್ವಾದ.",
