        "ASSFಗೆ ಅವರ ಪರಂಪರೆ ಕೇವಲ ಸ್ಫೂರ್ತಿಯ ಮೂಲವಲ್ಲ; ಅದು ಕಾರ್ಯಕ್ಕೆ ಮಾರ್ಗದರ್ಶಿ. ಪೀಳಿಗೆಗಳಿಂದ ಬಂದ ಜ್ಞಾನವನ್ನು ಕಾಪಾಡುವ ಮೂಲಕ ಮತ್ತು ಸಮುದಾಯಗಳನ್ನು ಕಾಳಜಿ, ಘನತೆ ಮತ್ತು ಕರುಣೆಯಿಂದ ಸೇವಿಸುವ ಮೂಲಕ ಫೌಂಡೇಶನ್ ಆ ಪರಂಪರೆಯನ್ನು ಗೌರವಿಸಲು ಪ್ರಯತ್ನಿಸುತ್ತದೆ.",
