          image: { alt: "ಕೆಳಗಿನ ಸಾಲುಗಳು ಹರಿದುಹೋದ, ತೆರೆದಿಟ್ಟ ಕೈಬರಹದ ಕಾಗದದ ಹಸ್ತಪ್ರತಿ, ‘BEFORE’ ಎಂದು ಬರೆದ ಚೀಟಿಯ ಪಕ್ಕದಲ್ಲಿ.", caption: "ಉಪಚಾರಕ್ಕೆ ಮೊದಲು ಕಾಗದದ ಹಸ್ತಪ್ರತಿ, KBJ/PM/047 ಎಂದು ದಾಖಲಿಸಲಾಗಿದೆ." },
