      note: "ಶಾಸ್ತ್ರಗಳ ಜೊತೆಗೆ ಈ ಸಂಗ್ರಹಗಳಲ್ಲಿ ತತ್ವಶಾಸ್ತ್ರ, ಗಣಿತ, ಖಗೋಳ, ವೈದ್ಯಶಾಸ್ತ್ರ, ವ್ಯಾಕರಣ ಮತ್ತು ಸಾಹಿತ್ಯಗಳಿವೆ — ಕೇವಲ ಧಾರ್ಮಿಕವಲ್ಲ, ಒಂದು ಬೌದ್ಧಿಕ ಪರಂಪರೆಯ ಭೌತಿಕ ದಾಖಲೆಗಳು.",
