      intro: "ಯಾವ ಎರಡು ಹಸ್ತಪ್ರತಿಗಳೂ ಒಂದೇ ತರಹ ಇರುವುದಿಲ್ಲ — ಕೆಲವೊಮ್ಮೆ ಎರಡು ಪತ್ರಗಳೂ ಇರುವುದಿಲ್ಲ. ಏನನ್ನಾದರೂ ಉಪಚರಿಸುವ ಮೊದಲು ಮೌಲ್ಯಮಾಪನವೇ ವಿಧಾನವನ್ನು ನಿರ್ಧರಿಸುತ್ತದೆ.",
