      body: "ASSF ಮುಖ್ಯ ಸಂರಕ್ಷಕರು, ಸಹಾಯಕ ಸಂರಕ್ಷಕರು ಮತ್ತು ತರಬೇತಿದಾರರನ್ನು ಉದ್ಯಮ-ಮಾನದಂಡದ ನಿಯಮಗಳಲ್ಲಿ ನೇಮಿಸುತ್ತದೆ — ಭಾರತದಲ್ಲಿ ತರಬೇತಿ ಪಡೆದ ಸಂರಕ್ಷಕರು ವಿರಳವಾಗಿರುವ ಕ್ಷೇತ್ರದಲ್ಲಿ ದೀರ್ಘಕಾಲೀನ ಸಾಮರ್ಥ್ಯವನ್ನು ಕಟ್ಟುತ್ತಾ. ಸ್ಥಳೀಯ ಸಂಸ್ಥೆಗಳಿಗೆ ಸುರಕ್ಷಿತ ನಿರ್ವಹಣೆ ಮತ್ತು ನಿವಾರಕ ಆರೈಕೆಯ ತರಬೇತಿ ನೀಡಲಾಗುತ್ತದೆ, ಇದರಿಂದ ಪಾಲಕರು ತಮ್ಮ ಸಂಗ್ರಹಗಳ ಆರೈಕೆಯನ್ನು ತಾವೇ ಮುಂದುವರಿಸಬಹುದು.",
