          body: "ಹೊಸೂರು ಗ್ರಾಮ ಪಂಚಾಯತ್ ಸಮುದಾಯ ಸೌಲಭ್ಯದ ಕೊರತೆಯನ್ನು ನಿಜವಾದ ಅಂತರವೆಂದು ಗುರುತಿಸಿತು. ASSF ದಾನವಾಗಿ ದೊರೆತ ಜಮೀನಿನಲ್ಲಿ ಬಹುಪಯೋಗಿ ಭವನವನ್ನು ನಿರ್ಮಿಸಿತು — ಸಭೆಗಳು, ಸಾಂಸ್ಕೃತಿಕ ಕಾರ್ಯಕ್ರಮಗಳು, ಪ್ರವಚನಗಳು ಮತ್ತು ಅತಿಥಿ ವಸತಿಗಾಗಿ.",
