          body: "ಆಚಾರ್ಯ ಶಾಂತಿ ಸಾಗರ ಫೌಂಡೇಶನ್ (ASSF)ನಲ್ಲಿ ಸಂರಕ್ಷಕ; ತಾಳೆಗರಿ ಮತ್ತು ಕಾಗದದ ಹಸ್ತಪ್ರತಿಗಳ ಸಂರಕ್ಷಣೆಯಲ್ಲಿ ಪರಿಣತರು.",
