            "ಆಚಾರ್ಯ ಶಾಂತಿ ಸಾಗರ ಫೌಂಡೇಶನ್ (ASSF)ನಲ್ಲಿ ಸಂರಕ್ಷಕ; ತಾಳೆಗರಿ ಮತ್ತು ಕಾಗದದ ಹಸ್ತಪ್ರತಿಗಳ ಸಂರಕ್ಷಣೆಯಲ್ಲಿ ಪರಿಣತರು. ಸಂರಕ್ಷಣಾ ತಂಡದ ಮೇಲ್ವಿಚಾರಣೆ, ಪ್ರಯೋಗಾಲಯ ನಿರ್ವಹಣೆ, ದಾಖಲೀಕರಣ, ಸ್ಥಿತಿ ಮೌಲ್ಯಮಾಪನ ಮತ್ತು ಶ್ರವಣಬೆಳಗೊಳದ NIPSARನಲ್ಲಿರುವ ASSF ಸಂರಕ್ಷಣಾ ಪ್ರಯೋಗಾಲಯದಲ್ಲಿ ಹಸ್ತಪ್ರತಿ ಸಂರಕ್ಷಣೆ ಅವರ ಹೊಣೆಗಳು. ಅವರು ವಸ್ತುಸಂಗ್ರಹಾಲಯ ಶಾಸ್ತ್ರದಲ್ಲಿ ಎಂ.ಎಸ್ಸಿ. ಪದವಿ ಹೊಂದಿದ್ದು, NRLC, ಲಖನೌನಲ್ಲಿ ಸಾಂಸ್ಕೃತಿಕ ಆಸ್ತಿಯ ಸಂರಕ್ಷಣೆಯ ವಿಶೇಷ ತರಬೇತಿ ಮತ್ತು AKST–ಟಾಟಾ ಟ್ರಸ್ಟ್ಸ್ ಉಪಕ್ರಮದಡಿ KIACನಲ್ಲಿ ‘ಕಾಗದದ ಸಂರಕ್ಷಣೆ: ಹಸ್ತಪ್ರತಿಗಳು ಮತ್ತು ಕಿರುಚಿತ್ರಕಲೆ’ಯ ಉನ್ನತ ತರಬೇತಿ ಪೂರೈಸಿದ್ದಾರೆ. ಸಾಂಸ್ಕೃತಿಕ ಪರಂಪರೆಯ ವೈಜ್ಞಾನಿಕ ಮತ್ತು ನೈತಿಕ ಸಂರಕ್ಷಣೆ ಹಾಗೂ ಸುಸ್ಥಿರ ಸಂರಕ್ಷಣಾ ಪದ್ಧತಿಗಳ ಬೆಳವಣಿಗೆಗೆ ಅವರು ಬದ್ಧರಾಗಿದ್ದಾರೆ.",
